"""Small, authored demo dataset, unrelated to the user's task dumps."""
from .db import Problem
from .services import make_solution, refresh_search

DEMO = [
    ("Кратчайший путь", "Дан неориентированный граф из n ≤ 100000 вершин и m ≤ 200000 рёбер с неотрицательными весами. Найдите кратчайшие расстояния от первой вершины до всех остальных.", ["Графы", "Алгоритм Дейкстры", "Кратчайшие пути"], 4, "O((n + m) log n)", "O(n + m)", "Поддерживаем расстояния в очереди с приоритетом"),
    ("Черепашка на поле", "Дана таблица n × m (1 ≤ n, m ≤ 1000) с неотрицательными числами. Из левого верхнего угла можно двигаться только вправо и вниз. Найдите максимальную сумму чисел на пути в правый нижний угол.", ["ДП на таблице", "Динамическое программирование"], 3, "O(nm)", "O(m)", "Для каждой клетки выбираем лучший путь сверху или слева"),
    ("Суммы на отрезках", "Дан массив из n ≤ 200000 целых чисел. Ответьте на q ≤ 200000 запросов суммы элементов на отрезке [l, r]. Массив не изменяется.", ["Префиксные суммы"], 2, "O(n + q)", "O(n)", "Вычитаем две префиксные суммы"),
    ("Рюкзак путешественника", "Есть n ≤ 100 предметов, вес каждого — целое число, и рюкзак вместимости W ≤ 10000. Найдите максимальную суммарную стоимость набора, вес которого не превышает W. Предмет берётся не более одного раза.", ["Задача о рюкзаке", "Динамическое программирование"], 4, "O(nW)", "O(W)", "Динамика по вместимости с обратным обходом весов"),
    ("Соединить города", "Дан связный неориентированный граф: n ≤ 100000 городов и m ≤ 200000 дорог. Найдите минимальную стоимость набора дорог, соединяющего все города.", ["Минимальное остовное дерево", "Алгоритм Краскала", "СНМ"], 5, "O(m log m)", "O(n + m)", "Сортируем рёбра и объединяем разные компоненты"),
    ("Потерянная подстрока", "Даны строка s длиной до 10^6 и образец p длиной до 10^5. Найдите все позиции вхождения образца в строку за линейное время.", ["Строки", "Алгоритм КМП", "Префикс-функция"], 3, "O(|s| + |p|)", "O(|p|)", "Используем префикс-функцию для переходов при несовпадении"),
    ("Динамические суммы", "Дан массив из n ≤ 200000 чисел. Выполните q ≤ 200000 операций двух типов: прибавить x к элементу i или найти сумму на отрезке [l, r].", ["Дерево Фенвика"], 5, "O((n + q) log n)", "O(n)", "Храним частичные суммы в дереве Фенвика"),
    ("Новая задача", "Дан массив целых чисел. Предложите интересную задачу на его основе. У этой демонстрационной записи пока нет решений.", [], None, "", "", ""),
]


def seed_demo(session):
    for title, statement, tags, difficulty, time, memory, idea in DEMO:
        problem = Problem(title=title, original_statement=statement, origin="Демонстрационный пример", statement_json={"canonical_name": title, "format": "standard", "abstract": statement, "objects": [], "task": title, "guarantees": [], "inferred_properties": [], "image_required": False})
        session.add(problem)
        session.flush()
        if tags:
            make_solution(session, problem, {"key_idea": idea, "sketch": idea, "tags": tags, "difficulty": difficulty, "complexity": {"time": time, "memory": memory}, "source": "llm", "trusted": False})
        refresh_search(session, problem)
